17	// extractTranscriptMetadata parses transcript bytes once and extracts the first user prompt,
18	// user turn count, and model name. Supports both JSONL (Claude Code, Cursor, OpenCode) and
19	// Gemini JSON format.
20	func extractTranscriptMetadata(data []byte) transcriptMetadata {
21		var meta transcriptMetadata
22	
23		// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
24		lines, err := transcript.ParseFromBytes(data)
25		if err == nil {
26			for _, line := range lines {
27				if line.Type == transcript.TypeUser {
28					if prompt := transcript.ExtractUserContent(line.Message); prompt != "" {
29						meta.TurnCount++
30						if meta.FirstPrompt == "" {
31							meta.FirstPrompt = prompt
32						}
33					}
34				}
35				if line.Type == transcript.TypeAssistant && meta.Model == "" {
36					var msg struct {
37						Model string `json:"model"`
38					}
39					if json.Unmarshal(line.Message, &msg) == nil && msg.Model != "" {
40						meta.Model = msg.Model
41					}
42				}
43			}
44			if meta.TurnCount > 0 || meta.Model != "" {
45				return meta
46			}
47		}
48	
49		// Fallback: try Gemini JSON format {"messages": [...]}
50		if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
51			meta.FirstPrompt = prompts[0]
52			meta.TurnCount = len(prompts)
53		}
54	
55		return meta
56	}
