1497	// setupAttachTestRepo creates a temp git repo with one commit and enables Entire.
1498	// Returns the repo directory. Caller must not use t.Parallel() (uses t.Chdir).
1499	func setupAttachTestRepo(t *testing.T) {
1500		t.Helper()
1501		tmpDir := t.TempDir()
1502		testutil.InitRepo(t, tmpDir)
1503		// attach runs `git commit --amend` via the git CLI, which inherits this
1504		// process's env. Pin git config (gc.auto=0, gc.autoDetach=false) so git
1505		// doesn't fork a detached `git gc` that keeps writing into the temp repo's
1506		// .git/objects and races t.TempDir cleanup ("directory not empty", COR-394).
1507		testutil.IsolateGitConfigEnv(t)
1508		testutil.WriteFile(t, tmpDir, "init.txt", "init")
1509		testutil.GitAdd(t, tmpDir, "init.txt")
1510		testutil.GitCommit(t, tmpDir, "init")
1511		t.Chdir(tmpDir)
1512		enableEntire(t, tmpDir)
1513	}
